            aWandererI = aWandererI ^ ((RotL64(aCross, 23U) + RotL64(aOrbiterB, 11U)) + aOrbiterF);
            aWandererH = aWandererH + (((RotL64(aScatter, 3U) + aOrbiterC) + RotL64(aOrbiterE, 5U)) + aNonceWordF);
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 44U) + RotL64(aOrbiterB, 51U)) + aOrbiterE);
            aWandererE = aWandererE + (((RotL64(aPrevious, 57U) + aOrbiterK) + RotL64(aOrbiterF, 54U)) + aPhaseBWandererUpdateSaltC[(((31U - aIndex) + 29U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererB, 29U) ^ aWandererD);
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererK, 53U));
