            aOrbiterF = (aWandererB + RotL64(aPrevious, 47U)) + 0xEBEE0BB457752520ULL;
            aOrbiterB = ((aWandererI + RotL64(aScatter, 41U)) + RotL64(aCarry, 5U)) + 0xCC9979A884F27C10ULL;
            aOrbiterE = ((aWandererG + RotL64(aPrevious, 43U)) + 0x319E4B322C7626BFULL) + aNonceWordN;
            aOrbiterH = ((aWandererD + RotL64(aIngress, 3U)) + 0xB7A729BCBEA8AFB9ULL) + aPhaseCOrbiterAssignSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterD = ((aWandererH + RotL64(aScatter, 37U)) + 0x3AAB631AAD5B76E0ULL) + aNonceWordA;
            aOrbiterA = ((aWandererC + RotL64(aCross, 57U)) + 0xCA41D74C2C406DD5ULL) + aNonceWordC;
            aOrbiterC = ((aWandererK + RotL64(aPrevious, 13U)) + RotL64(aCarry, 51U)) + 0x7347DA3C961996AFULL;
            aOrbiterJ = ((aWandererJ + RotL64(aCross, 29U)) + RotL64(aCarry, 27U)) + 0x29BFB929BA485F89ULL;
            aOrbiterG = ((aWandererE + RotL64(aIngress, 54U)) + 0x7B4F318DA4D2E4A0ULL) + aPhaseCOrbiterAssignSaltF[(((31U - aIndex) + 4U)) & S_SALT1];
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x2BBE2DF23BE7BF7BULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x54173BD0E811E09EULL;
            aOrbiterF = RotL64((aOrbiterF * 0xA167C7AFBB2F37A7ULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x28791FB732D1515DULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0xBB9EA7C9BE911CC9ULL) ^ aNonceWordD;
            aOrbiterI = RotL64((aOrbiterI * 0xF1FA483CD1E9D4DBULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x7E34340B70F22B88ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x3EFBB730BFAAD4DAULL;
            aOrbiterA = RotL64((aOrbiterA * 0x17D36F9BCB50A215ULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xBC71078CF0EC4811ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xEB0FC3483B9C1A2DULL;
            aOrbiterB = RotL64((aOrbiterB * 0xB90BE88D3BADE41BULL), 43U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0xED2D5BB6CF9AE572ULL;
