            //
            aOrbiterF = ((aOrbiterF + aOrbiterH) + 0xFCFD360B2CEC4910ULL) + aNonceWordM;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x599CFC8C877CADCCULL;
            aOrbiterC = RotL64((aOrbiterC * 0x17BC5EE3C9A5ADF9ULL), 5U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0x059D3692556E06D9ULL) + aPhaseCOrbiterUpdateSaltD[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0xBF5992F05909A6E9ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x93F279D895C453CFULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xB911CE0C2642C0FDULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0xE77228CE879867ABULL;
            aOrbiterH = RotL64((aOrbiterH * 0xB3989DA194A629CFULL), 41U);
            //
            aOrbiterC = (((aOrbiterC + aOrbiterA) + 0xF649B0A9E30CBDEAULL) + aPhaseCOrbiterUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1]) + aNonceWordI;
