            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x65AFECC575F86EF2ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0x7E754153BCF6F1C2ULL) ^ aPhaseCOrbiterUpdateSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
