            aOrbiterG = (((aWandererH + RotL64(aCross, 43U)) + RotL64(aCarry, 39U)) + 0xE51C90A1E7816A2EULL) + aPhaseBOrbiterAssignSaltB[((aIndex + 25U)) & S_SALT1];
            aOrbiterH = ((aWandererI + RotL64(aScatter, 28U)) + RotL64(aCarry, 51U)) + 0xAA5CB6591AA28753ULL;
            aOrbiterB = (aWandererD + RotL64(aIngress, 37U)) + 0x0FB59292A34733AEULL;
            aOrbiterD = ((aWandererA + RotL64(aPrevious, 13U)) + RotL64(aCarry, 13U)) + 0xF9AA2AC9D2D13AC1ULL;
            //
