            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0xD2BC257D58D1D8D6ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x3D84E2FBA8316E23ULL), 5U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterK) + 0x4AE420C977AAEF33ULL) + aPhaseBOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x9C6B81A5ACB1172CULL) ^ aPhaseBOrbiterUpdateSaltF[(((31U - aIndex) + 18U)) & S_SALT1];
