            aOrbiterD = (aOrbiterD + aOrbiterH) + 0xC40BEAEEC2365B30ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0xA207CA13E8C3255CULL;
            aOrbiterA = RotL64((aOrbiterA * 0x5AF5330182E6F69BULL), 43U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x541436620AA2D4F3ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0x5B01675A8FDC34FEULL;
            aOrbiterG = RotL64((aOrbiterG * 0x994EB2D1D37E51E9ULL), 27U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0x34D786F8B0FC32DFULL) + aPhaseBOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x3A4AF195F0EA7CA2ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x0B726BF85A1C6CEFULL), 57U);
            //
