            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCross, 57U) + RotL64(aPrevious, 27U)) ^ (RotL64(aIngress, 39U) + RotL64(aCarry, 6U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterJ = (aWandererH + RotL64(aIngress, 3U)) + 0x2A2AC6A287552219ULL;
            aOrbiterB = (aWandererF + RotL64(aCross, 19U)) + 0x79267BA324F2BC2AULL;
            aOrbiterE = ((aWandererC + RotL64(aScatter, 40U)) + RotL64(aCarry, 35U)) + 0x7463728F4DE33134ULL;
            aOrbiterK = (((aWandererJ + RotL64(aPrevious, 47U)) + RotL64(aCarry, 51U)) + 0x76F6ACFB533838E0ULL) + aPhaseBOrbiterAssignSaltE[((aIndex + 16U)) & S_SALT1];
            aOrbiterF = ((aWandererD + RotL64(aIngress, 27U)) + RotL64(aCarry, 23U)) + 0x46BA5A48CAE92808ULL;
            aOrbiterI = (aWandererI + RotL64(aPrevious, 13U)) + 0x070CDAEB2E797261ULL;
            aOrbiterA = ((aWandererK + RotL64(aCross, 53U)) + 0x939A63D01B2B83F6ULL) + aPhaseBOrbiterAssignSaltC[(((31U - aIndex) + 24U)) & S_SALT1];
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x2DDB7CCB3D2A6BF2ULL) + aPhaseBOrbiterUpdateSaltF[((aIndex + 12U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x183251E4DCE43CCCULL;
