            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0x6A0ADF3028726283ULL) + aPhaseBOrbiterUpdateSaltE[((aIndex + 15U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xB826136B1CE0482FULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xAC992BA89AA99105ULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x9BB41C6DCA5F905AULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterA) ^ 0x8CEFAE52E73EC1CFULL) ^ aPhaseBOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1];
