            aOrbiterE = ((aWandererH + RotL64(aPrevious, 14U)) + RotL64(aCarry, 39U)) + 0x2C9EBC24A4CD0AD3ULL;
            aOrbiterC = (aWandererB + RotL64(aIngress, 23U)) + 0xF03D7E90FA7A5F31ULL;
            aOrbiterJ = (((aWandererC + RotL64(aCross, 35U)) + RotL64(aCarry, 23U)) + 0xA69C6B9BA4204BAAULL) + aPhaseCOrbiterAssignSaltF[((aIndex + 24U)) & S_SALT1];
